namespace {
constexpr uint32_t begin=296,strides[]={0,8,1,192,36,24,44,40,40,4};
uint32_t u32(const uint8_t*p){return uint32_t(p[0])|uint32_t(p[1])<<8|uint32_t(p[2])<<16|uint32_t(p[3])<<24;}
float f32(const uint8_t*p){auto n=u32(p);float v;std::memcpy(&v,&n,4);return v;}Vec2 vec(const uint8_t*p){return {f32(p),f32(p+4)};}
FieldGeometryTransform transform(const uint8_t*p){return {vec(p),vec(p+8),vec(p+16)};}
uint32_t crc(const uint8_t*p,size_t n){uint32_t c=~0u;while(n--){c^=*p++;for(unsigned j=0;j<8;++j)c=(c>>1)^((c&1)?0xedb88320u:0u);}return ~c;}
bool finite(float v){return std::isfinite(v)&&std::abs(v)<1000000;}bool finite(Vec2 v){return finite(v.x)&&finite(v.y);}
bool path(std::string_view s){if(s.empty()||s.front()=='/'||s.back()=='/'||s.find('\\')!=s.npos)return false;size_t b=0;while(b<s.size()){auto e=s.find('/',b);if(e==s.npos)e=s.size();auto p=s.substr(b,e-b);if(p.empty()||p=="."||p=="..")return false;b=e+1;}return true;}
bool direction(Vec2 d){return d.x!=0||d.y!=0;}
}
uint32_t FieldDoorData::count(uint32_t k)const{return valid()&&k>=1&&k<=u32(bytes_.data()+20)?u32(bytes_.data()+128+24*(k-1)+4):0;}
const uint8_t*FieldDoorData::record(uint32_t k,uint32_t i)const{return i<count(k)?bytes_.data()+u32(bytes_.data()+128+24*(k-1)+12)+size_t(i)*strides[k]:nullptr;}
std::string_view FieldDoorData::string(uint32_t i)const{auto r=record(1,i);return r?std::string_view(reinterpret_cast<const char*>(record(2,u32(r))),u32(r+4)):std::string_view{};}
FieldIdentity FieldDoorData::identity()const{FieldIdentity id;if(valid()){id.scene_id=u32(bytes_.data()+36);std::copy_n(bytes_.data()+40,20,id.upstream_commit.begin());std::copy_n(bytes_.data()+60,32,id.source_sha256.begin());}return id;}
std::string_view FieldDoorData::source_scene()const{return valid()?string(u32(bytes_.data()+124)):std::string_view{};}
uint32_t FieldDoorData::door_count()const{return count(3);}
FieldDoorDescriptor FieldDoorData::door(uint32_t i)const{FieldDoorDescriptor n;auto r=record(3,i);if(!r)return n;uint32_t*ints[]={&n.id,&n.ready,&n.node,&n.marker,&n.audio,&n.shape,&n.layer,&n.mask,&n.flags,&n.pause_mode,&n.target_name,&n.target_path,&n.sound,&n.end_sound,&n.in_anim,&n.out_anim,&n.flag};for(unsigned j=0;j<17;++j)*ints[j]=u32(r+4*j);r+=68;n.target=vec(r);n.direction=vec(r+8);n.in_speed=f32(r+16);n.out_speed=f32(r+20);n.music_fade=f32(r+24);for(unsigned j=0;j<4;++j){n.in_color[j]=f32(r+28+4*j);n.out_color[j]=f32(r+44+4*j);}n.body_transform=transform(r+60);n.marker_transform=transform(r+84);n.shape_offset=vec(r+108);n.extents=vec(r+116);return n;}
bool FieldDoorData::find(uint32_t id,FieldDoorDescriptor&out)const{for(uint32_t i=0;i<door_count();++i){auto n=door(i);if(n.id==id){out=n;return true;}}return false;}
FieldDoorAudio FieldDoorData::audio(uint32_t id)const{for(uint32_t i=0;i<count(6);++i){auto r=record(6,i);if(u32(r)==id){FieldDoorAudio a{u32(r),u32(r+4),u32(r+8),{}};std::copy_n(r+12,32,a.sha.begin());return a;}}return {};}
bool FieldDoorData::source_hash(std::string_view name,std::array<uint8_t,32>&h)const{for(uint32_t i=0;i<count(4);++i){auto r=record(4,i);if(string(u32(r))==name){std::copy_n(r+4,32,h.begin());return true;}}return false;}
std::string_view FieldDoorData::script()const{auto r=record(5,0);return r?string(u32(r)):std::string_view{};}
std::array<uint8_t,32>FieldDoorData::script_sha()const{std::array<uint8_t,32>h{};source_hash(script(),h);return h;}
std::string_view FieldDoorData::none()const{auto r=record(5,0);return r?string(u32(r+16)):std::string_view{};}float FieldDoorData::ground_offset()const{auto r=record(5,0);return r?f32(r+20):0;}
uint32_t FieldDoorData::capability()const{return valid()?u32(bytes_.data()+32):0;}
std::string_view FieldDoorData::body_method()const{auto p=record(9,0);return p?string(u32(p)):std::string_view{};}
bool FieldDoorData::house_continuation()const{return valid()&&u32(bytes_.data()+8)>=2&&count(8)==1;}
std::string_view FieldDoorData::old_region()const{auto p=record(8,0);return p?string(u32(p)):std::string_view{};}
std::string_view FieldDoorData::old_root_name()const{auto p=record(8,0);return p?string(u32(p+4)):std::string_view{};}
std::string_view FieldDoorData::area_left_signal()const{auto p=record(8,0);return p?string(u32(p+8)):std::string_view{};}
std::string_view FieldDoorData::door_signal(FieldDoorSignal s)const{auto p=record(8,0);auto role=uint32_t(s);return p&&role<3?string(u32(p+12+role*4)):std::string_view{};}
std::string_view FieldDoorData::scene_changed_signal()const{auto p=record(8,0);return p?string(u32(p+24)):std::string_view{};}
bool FieldDoorData::empty_destination_parameters()const{auto p=record(8,0);return p&&u32(p+32)==1;}
bool FieldDoorData::old_area_has_listeners()const{auto p=record(8,0);return p&&u32(p+36)!=0;}
bool FieldDoorData::load(const uint8_t*p,size_t n,const FieldIdentity&id,std::string&e){if(!p||n<begin||n>4*1024*1024){e="Door source size rejected";return false;}return admit(std::vector<uint8_t>(p,p+n),id,e);}
bool FieldDoorData::load_file(const char*p,const FieldIdentity&id,std::string&e){if(!p||!*p){e="Door path rejected";return false;}FILE*f=std::fopen(p,"rb");if(!f){e="Cannot open Door resource";return false;}if(std::fseek(f,0,SEEK_END)){std::fclose(f);e="Door seek failed";return false;}long n=std::ftell(f);if(n<static_cast<long>(begin)||n>4*1024*1024||std::fseek(f,0,SEEK_SET)){std::fclose(f);e="Door file size rejected";return false;}std::vector<uint8_t>b(static_cast<size_t>(n));auto got=std::fread(b.data(),1,b.size(),f);bool closed=std::fclose(f)==0;if(got!=b.size()||!closed){e="Door read failed";return false;}return admit(std::move(b),id,e);}
