 std::unordered_map<std::string_view,std::array<uint8_t,32>>proof;for(uint32_t i=0;i<c.count(4);++i){auto r=c.record(4,i);std::array<uint8_t,32>h{};std::copy_n(r+4,32,h.begin());if(u32(r)>=c.count(1)||!path(c.string(u32(r)))||std::all_of(h.begin(),h.end(),[](uint8_t v){return !v;})||!proof.emplace(c.string(u32(r)),h).second)return fail("Door source proof rejected");}auto root=proof.find(c.source_scene());if(root==proof.end()||root->second!=id.source_sha256)return fail("Door root proof rejected");auto profile=c.record(5,0);for(unsigned j=0;j<4;++j)if(u32(profile+4*j)>=c.count(1)||proof.find(c.string(u32(profile+4*j)))==proof.end())return fail("Door script closure rejected");if(u32(profile+16)>=c.count(1)||c.none().empty()||!finite(c.ground_offset())||c.ground_offset()<0)return fail("Door source tuning rejected");
 std::unordered_set<uint32_t>ids,children,audios,targets;std::unordered_set<std::string_view>nodes;uint32_t prev=0;for(uint32_t i=0;i<c.door_count();++i){auto n=c.door(i);if(!n.id||!ids.insert(n.id).second||!n.marker||!n.audio||!n.shape||n.marker==n.audio||n.marker==n.shape||n.audio==n.shape||!children.insert(n.marker).second||!children.insert(n.audio).second||!children.insert(n.shape).second||n.flags>511||n.pause_mode>2||(i&&n.ready<=prev))return fail("Door node/Ready flags rejected");prev=n.ready;uint32_t strings[]={n.node,n.target_name,n.target_path,n.sound,n.end_sound,n.in_anim,n.out_anim,n.flag};for(auto s:strings)if(s>=c.count(1))return fail("Door string reference rejected");if(!path(c.string(n.node))||!nodes.insert(c.string(n.node)).second||c.string(n.in_anim).empty()||!finite(n.target)||!finite(n.direction)||!finite(n.in_speed)||!finite(n.out_speed)||n.in_speed<=0||n.out_speed<=0||!finite(n.music_fade)||n.music_fade<0||!finite(n.shape_offset)||!finite(n.extents)||n.extents.x<=0||n.extents.y<=0)return fail("Door source properties rejected");for(auto t:{n.body_transform,n.marker_transform})if(!finite(t.x)||!finite(t.y)||!finite(t.origin)||t.x.x*t.y.y-t.x.y*t.y.x==0)return fail("Door source transform rejected");for(auto color:{n.in_color,n.out_color})for(float v:color)if(!finite(v)||v<0||v>1)return fail("Door fade color rejected");auto target=c.string(n.target_path);if(c.string(n.target_name).empty()!=target.empty()||(!target.empty()&&(!path(target)||proof.find(target)==proof.end())))return fail("Door target proof rejected");for(auto s:{n.sound,n.end_sound}){auto sound=c.string(s);if(!sound.empty()&&sound!=c.none()&&(!path(sound)||proof.find(sound)==proof.end()))return fail("Door audio source rejected");}auto a=c.audio(n.audio);if(a.id!=n.audio)return fail("Door onready audio missing");}
