bool FieldDoorRuntime::initialize(const FieldDoorData&d,FieldDoorHost h,std::string&e){if(data_){e="Door runtime already initialized";return false;}if(!d.valid()||!h.observe||!h.resolve_onready||!h.connect_body||!h.prepare_destination||!h.release_candidate||!h.pause_player||!h.set_entering||!h.flag_exists||!h.write_flag||!h.music_changers||!h.stop_music||!h.play_audio||!h.fade||!h.emit||!h.marker_world||!h.set_player_global_position||!h.persistent||!h.schedule_deferred||!h.clear_enemies||!h.scene_step||!h.emit_scene_changed||!h.camera_current_and_visible||!h.fade_cut||!h.direction_and_input||!h.update_party||!h.unpause_player||!h.queue_free||!h.set_respawn){e="Door actual lifecycle/transition Host incomplete";return false;}data_=&d;host_=std::move(h);e.clear();return true;}
bool FieldDoorRuntime::poison(std::string&e){phase_=FieldDoorPhase::Poisoned;if(e.empty())e="Door source lifecycle operation failed";return false;}
bool FieldDoorRuntime::ready(uint32_t id,std::string&e){FieldDoorDescriptor n;if(!data_||phase_==FieldDoorPhase::Poisoned||!data_->find(id,n)||std::find(ready_.begin(),ready_.end(),id)!=ready_.end()||(had_ready_&&n.ready<=last_ready_)){e="Door Ready source/order rejected";return false;}if(!host_.resolve_onready(n,data_->audio(n.audio),e)||!host_.connect_body(id,[this,id](uint64_t body,std::string&error){return body_entered(id,body,error);},e))return poison(e);ready_.push_back(id);last_ready_=n.ready;had_ready_=true;e.clear();return true;}
bool FieldDoorRuntime::select(uint32_t id,uint64_t player,const FieldDoorContext&context,std::string&e){if(!data_||!player||std::find(ready_.begin(),ready_.end(),id)==ready_.end()||!data_->find(id,active_)){e="Door live source instance not Ready";return false;}if(phase_!=FieldDoorPhase::Idle&&phase_!=FieldDoorPhase::Done){e="Door source coroutine already active";return false;}player_=player;candidate_={};return prepare(context,e);}
bool FieldDoorRuntime::prepare(const FieldDoorContext&context,std::string&e){bool next_same=data_->string(active_.target_name).empty()||context.current_scene_name==data_->string(active_.target_name);if(candidate_.token&&(next_same||context.in_cutscene)){if(!host_.release_candidate(candidate_,false,e))return false;candidate_={};}same_=next_same;if(!same_&&!context.in_cutscene&&!candidate_.token){if(!host_.prepare_destination(active_,candidate_,e))return false;std::array<uint8_t,32>h{};if(!data_->source_hash(data_->string(active_.target_path),h)||!candidate_.token||candidate_.path!=data_->string(active_.target_path)||candidate_.pin!=data_->identity().upstream_commit||candidate_.source_sha!=h){std::string release;host_.release_candidate(candidate_,false,release);candidate_={};e="Door destination candidate identity/admission rejected";return false;}}e.clear();return true;}
bool FieldDoorRuntime::body_entered(uint32_t id,uint64_t body,std::string&e){if(!data_||phase_==FieldDoorPhase::Poisoned){e="Door runtime unavailable";return false;}FieldDoorContext c;if(!host_.observe(c,e))return false;if(body!=c.player||c.entering){e.clear();return true;}if(phase_==FieldDoorPhase::BodyIdle){FieldDoorDescriptor n;if(!data_->find(id,n)||std::find(ready_.begin(),ready_.end(),id)==ready_.end()){e="Door body signal source not Ready";return false;}if(!host_.pause_player(body,false,true,e))return poison(e);body_waiters_.push_back({id,body});e.clear();return true;}if(!select(id,body,c,e))return false;if(!host_.pause_player(body,false,true,e))return poison(e);phase_=FieldDoorPhase::BodyIdle;e.clear();return true;}
bool FieldDoorRuntime::enter(uint32_t id,uint64_t player,std::string&e){if(!data_||phase_==FieldDoorPhase::Poisoned){e="Door runtime unavailable";return false;}FieldDoorContext c;if(!host_.observe(c,e))return false;if(c.entering){e.clear();return true;}if(!player)player=c.player;if(!select(id,player,c,e))return false;return start(e);}
bool FieldDoorRuntime::start(std::string&e){FieldDoorContext c;if(!host_.observe(c,e))return poison(e);if(c.entering){if(candidate_.token&&!host_.release_candidate(candidate_,false,e))return poison(e);candidate_={};phase_=FieldDoorPhase::Idle;e.clear();return true;}if(!prepare(c,e))return poison(e);if(!host_.set_entering(true,e))return poison(e);if(c.in_cutscene){if(candidate_.token&&!host_.release_candidate(candidate_,false,e))return poison(e);candidate_={};phase_=FieldDoorPhase::Done;e.clear();return true;}
 // The source intentionally leaves entering_door true in the cutscene branch.
 if(!same_&&!candidate_.token){e="Door destination lost admission before transition";return poison(e);}auto flag=data_->string(active_.flag);if(!flag.empty()){bool exists=false;if(!host_.flag_exists(flag,exists,e))return poison(e);if(exists&&!host_.write_flag(flag,(active_.flags&128)!=0,e))return poison(e);}if(!same_&&(active_.flags&256)){std::vector<uint64_t>music;if(!host_.music_changers(music,e))return poison(e);for(auto id:music)if(!id||!host_.stop_music(id,active_.music_fade,e))return poison(e);}if(!audio(active_.sound,e))return poison(e);phase_=FieldDoorPhase::FadeIn;if(!host_.fade(true,data_->string(active_.in_anim),active_.in_color,active_.in_speed,e))return poison(e);e.clear();return true;}
bool FieldDoorRuntime::audio(uint32_t key,std::string&e){auto s=data_->string(key);if(s.empty()||s==data_->none()){e.clear();return true;}std::array<uint8_t,32>h{};if(!data_->source_hash(s,h)){e="Door sound source absent";return false;}return host_.play_audio(active_.audio,s,h,e);}
bool FieldDoorRuntime::after_warp(std::string&e){if((active_.flags&64)&&!host_.camera_current_and_visible(player_,e))return poison(e);if(!host_.fade_cut(e))return poison(e);if(direction(active_.direction)&&!host_.direction_and_input(player_,active_.direction,e))return poison(e);phase_=FieldDoorPhase::PartyIdle;e.clear();return true;}
bool FieldDoorRuntime::fade_in_done(std::string&e){if(phase_!=FieldDoorPhase::FadeIn){e="Door unexpected fade_in_done";return false;}if(!host_.emit(active_.id,FieldDoorSignal::Entered,e))return poison(e);if(same_){Vec2 p;if(!host_.marker_world(active_.marker,p,e)||!finite(p))return poison(e);p.y-=data_->ground_offset();if(!host_.set_player_global_position(player_,p,e)||!host_.emit(active_.id,FieldDoorSignal::MovedPlayer,e))return poison(e);return after_warp(e);}if(!host_.persistent(active_.id,true,e)||!host_.schedule_deferred(active_.id,e))return poison(e);phase_=FieldDoorPhase::Deferred;if(!host_.clear_enemies(e))return poison(e);e.clear();return true;}
bool FieldDoorRuntime::deferred_commit(std::string&e){if(phase_!=FieldDoorPhase::Deferred||!candidate_.token){e="Door unexpected deferred SceneTree commit";return false;}Vec2 position=active_.target;position.y-=data_->ground_offset();for(uint32_t s=uint32_t(FieldDoorSceneStep::DetachPlayer);s<=uint32_t(FieldDoorSceneStep::UpdateKeyIndicator);++s)if(!host_.scene_step(static_cast<FieldDoorSceneStep>(s),candidate_,player_,position,{},e))return poison(e);phase_=FieldDoorPhase::TreeChanged;e.clear();return true;}
bool FieldDoorRuntime::tree_changed(std::string&e){if(phase_!=FieldDoorPhase::TreeChanged){e="Door unexpected tree_changed";return false;}phase_=FieldDoorPhase::SceneIdle;e.clear();return true;}
bool FieldDoorRuntime::idle_frame(std::string&e){if(phase_==FieldDoorPhase::BodyIdle){auto waiters=std::move(body_waiters_);body_waiters_.clear();if(!start(e))return false;for(const auto&w:waiters)if(!enter(w.first,w.second,e))return poison(e);return true;}if(phase_==FieldDoorPhase::SceneIdle){Vec2 p=active_.target;p.y-=data_->ground_offset();if(!host_.scene_step(FieldDoorSceneStep::EnablePlayerCollisions,candidate_,player_,p,{},e)||!host_.emit_scene_changed(e))return poison(e);return after_warp(e);}if(phase_==FieldDoorPhase::PartyIdle){if(!host_.update_party(player_,e))return poison(e);auto anim=data_->string(active_.out_anim);if(anim.empty())anim=data_->string(active_.in_anim);phase_=FieldDoorPhase::FadeMostly;if(!host_.fade(false,anim,active_.out_color,active_.out_speed,e))return poison(e);e.clear();return true;}e="Door idle event has no source continuation";return false;}
bool FieldDoorRuntime::fade_out_mostly_done(std::string&e){if(phase_!=FieldDoorPhase::FadeMostly){e="Door unexpected fade_out_mostly_done";return false;}if(!audio(active_.end_sound,e))return poison(e);FieldDoorContext c;if(!host_.observe(c,e))return poison(e);if(!c.in_cutscene&&(active_.flags&32)){if(direction(active_.direction)&&!host_.direction_and_input(player_,active_.direction,e))return poison(e);if(!host_.unpause_player(player_,e))return poison(e);}if(!same_){if(!host_.persistent(active_.id,false,e)||!host_.queue_free(active_.id,e))return poison(e);}if((active_.flags&8)&&!host_.set_respawn(e))return poison(e);if(!host_.set_entering(false,e)||!host_.emit(active_.id,FieldDoorSignal::Done,e))return poison(e);if(candidate_.token&&!host_.release_candidate(candidate_,true,e))return poison(e);candidate_={};phase_=FieldDoorPhase::Done;e.clear();return true;}
